// Generated by qaia-playwright:automate — AC6 (the sort control's narrow-viewport presentation and
// its persistence across a drawer cycle). Mobile = device emulation only (D100).
const { test, expect } = require('../fixtures');

test.describe('AC6 — sort-control rendering across the 899/900 px boundary', () => {
  for (const [width, rendered] of [[899, 40], [900, 223]]) {
    test(`@QAIA-US-EVAL-013-014 @AC6 @P2 @boundary — at ${width} px the sort control renders ${rendered} CSS px wide`,
      async ({ signedIn }) => {
        const { page, inventoryPage } = signedIn;
        await page.setViewportSize({ width, height: 900 });
        expect(await inventoryPage.sortControlWidth()).toBe(rendered);
      });
  }
});

test('@QAIA-US-EVAL-013-015 @AC6 @P2 @state-transition — the chosen sort order survives a drawer open/close cycle',
  async ({ signedIn }) => {
    const { inventoryPage, drawer } = signedIn;
    await inventoryPage.sortBy('za');
    await expect(inventoryPage.sortControl).toHaveValue('za');

    await drawer.open();
    await drawer.close();

    await expect(inventoryPage.sortControl).toHaveValue('za');
    await expect(inventoryPage.items.first().getByTestId('inventory-item-name'))
      .toHaveText('Test.allTheThings() T-Shirt (Red)');
  });
